function E(t,c,x){var e=document.createElementNS(NS,t);if(c)e.setAttribute("class",c);if(x!=null)e.textContent=x;return e;}
function LK(u,c,x){var a=E("a",c,x);a.setAttribute("href",u);a.setAttribute("target","_blank");a.setAttribute("rel","noopener noreferrer");a.setAttribute("title",u);a.setAttribute("data-s",u.toLowerCase());return a;}
function lab(u){try{var a=new URL(u),p=a.pathname+a.search,full=a.host+(a.pathname==="/"&&!a.search?"":p);if(full.length<=46)return full;var s=a.pathname.split("/").filter(Boolean),l=s.length?s[s.length-1]:"";return a.host+(l?"/\u2026/"+l:"");}catch(e){return u;}}
function cnt(g){return g.rec?g.rec.length:g.runs.reduce(function(a,r){return a+r.u.length;},0);}
Array.prototype.forEach.call(document.querySelectorAll("img.logo"),function(i){i.setAttribute("src",LOGO);});
var gate=$("gate"),mainL=$("mainL"),intro=$("intro"),inp=$("gkey"),msg=$("gmsg");
function render(){
var list=$("list"),jumps=$("jumps"),total=0;
GROUPS.forEach(function(g,gi){
var n=cnt(g);total+=n;
var sec=E("section","grp"+(g.feat?" feat":""));sec.id="g"+gi;sec.setAttribute("data-g",g.n.toLowerCase());
var det=E("details");det.setAttribute("open","open");
var sm=E("summary");sm.appendChild(E("span","gname serif",g.n));
if(g.note)sm.appendChild(E("span","gnote",g.note));
sm.appendChild(E("span","gcount",n+(n===1?" link":" links")));
det.appendChild(sm);
var body=E("div","gbody");
if(g.sub)body.appendChild(E("p","gsub",g.sub));
if(g.rec){var tg=E("div","tiles");g.rec.forEach(function(r){var a=LK(r[1],"tile");a.appendChild(E("span","tname serif",r[0]));a.appendChild(E("span","thost mono",lab(r[1])));tg.appendChild(a);});body.appendChild(tg);}
g.runs.forEach(function(r){var blk=E("div","blk");
if(r.k==="c"){if(r.cap)blk.appendChild(E("div","cap mono",r.cap));var grid=E("div","chips");r.u.forEach(function(x){grid.appendChild(LK(x[0],"chip",x[1]));});blk.appendChild(grid);}
else{var rows=E("div","rows");r.u.forEach(function(u){rows.appendChild(LK(u,"row mono",lab(u)));});blk.appendChild(rows);}
body.appendChild(blk);});
det.appendChild(body);sec.appendChild(det);list.appendChild(sec);
var c=E("button","jump",g.n);c.setAttribute("type","button");
c.addEventListener("click",function(){det.setAttribute("open","open");sec.scrollIntoView({behavior:reduce?"auto":"smooth",block:"start"});});
jumps.appendChild(c);});
$("meta").textContent=total.toLocaleString("en-US")+" links in "+GROUPS.length+" groups";}
function filt(){
var v=$("q").value.trim().toLowerCase(),all=0,secs=$("list").children,i,j,k;
for(i=0;i<secs.length;i++){var sec=secs[i],gm=!!v&&sec.getAttribute("data-g").indexOf(v)>-1,sh=0,as=sec.querySelectorAll("a");
for(j=0;j<as.length;j++){var m=!v||gm||as[j].getAttribute("data-s").indexOf(v)>-1;as[j].style.display=m?"":"none";if(m)sh++;}
var bl=sec.querySelectorAll(".blk");
for(j=0;j<bl.length;j++){var bs=bl[j].querySelectorAll("a"),bv=0;for(k=0;k<bs.length;k++){if(bs[k].style.display!=="none")bv++;}bl[j].style.display=(!v||bv)?"":"none";}
sec.style.display=(!v||sh||gm)?"":"none";
if(v&&sh)sec.querySelector("details").setAttribute("open","open");
all+=sh;}
$("none").style.display=(v&&!all)?"block":"none";}
$("q").addEventListener("input",filt);
function setAll(o){var d=$("list").querySelectorAll("details"),i;for(i=0;i<d.length;i++){if(o)d[i].setAttribute("open","open");else d[i].removeAttribute("open");}}
$("expand").addEventListener("click",function(){setAll(true);});
$("collapse").addEventListener("click",function(){setAll(false);});
function setAdmin(on){$("abtn").style.display=on?"inline-block":"none";if(!on)$("admin").classList.add("off");}
function unlock(k){if(!built){render();built=true;}setAdmin(isAdmin(k));gate.classList.add("off");mainL.classList.remove("off");}
function go(){var k=inp.value.trim();if(!k)return;if(ok(k)){try{localStorage.setItem("lv_key",k);}catch(e){}unlock(k);}else{msg.textContent="That key isn't valid. Check it and try again.";}}
$("gbtn").addEventListener("click",go);inp.addEventListener("keydown",function(e){if(e.key==="Enter")go();});
function enter(){if(armed)return;armed=true;intro.classList.add("off");var sk=null;try{sk=localStorage.getItem("lv_key");}catch(e){}
if(sk&&ok(sk)){unlock(sk);}else{gate.classList.remove("off");setTimeout(function(){inp.focus();},500);}}
intro.addEventListener("click",enter);
intro.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();enter();}});
intro.focus();
$("abtn").addEventListener("click",function(){$("admin").classList.remove("off");$("acode").focus();});
function closeAdmin(){$("admin").classList.add("off");$("alist").textContent="";$("alist").style.display="none";$("acopy").style.display="none";$("acode").value="";$("amsg").textContent="Enter the admin code to decrypt the keys.";}
$("aclose").addEventListener("click",closeAdmin);
function show(){var c=$("acode").value;if(!c)return;if(!(window.crypto&&crypto.subtle)){$("amsg").textContent="This needs a secure page (https) or the file opened from disk.";return;}$("amsg").textContent="Decrypting...";reveal(c).then(function(t){$("alist").textContent=t;$("alist").style.display="block";$("acopy").style.display="inline-block";$("amsg").textContent=t.split("\n").length+" keys. Closing this panel hides them again.";}).catch(function(){$("amsg").textContent="Wrong code.";});}
$("ago").addEventListener("click",show);$("acode").addEventListener("keydown",function(e){if(e.key==="Enter")show();});
$("acopy").addEventListener("click",function(){var t=$("alist").textContent;try{navigator.clipboard.writeText(t).then(function(){$("amsg").textContent="Copied.";},function(){$("amsg").textContent="Copy blocked. Select the keys and copy them manually.";});}catch(e){$("amsg").textContent="Copy blocked. Select the keys and copy them manually.";}});
window.addEventListener("beforeunload",function(e){if(!armed)return;e.preventDefault();e.returnValue=MSG;return MSG;});
